  Context {HCEIL : HeapCeil}.
  Lemma land_127 : forall x, Z.land x 127 = x mod 128.
  Proof. intros. change 127 with (Z.ones 7). rewrite Z.land_ones by lia. reflexivity. Qed.
  Lemma wrap_mod_128 : forall e, bv_unsigned (Z_to_bv 64 e) mod 128 = e mod 128.
  Proof. intros e. exact (unsigned_wrap_mod e 7 ltac:(lia)). Qed.
  (* [comment removed for export] *)
  Lemma shad_of_CB : forall m A k bs, 0 <= A -> A mod 8 = 0 ->
    rw_cells bsegs m (sh A) [CB k bs] -> SHAD m A bs.
  Proof.
    intros m A k bs H0 H8 RC. split; [exact H0|]. split; [exact H8|]. exact (u8arr_of_rw_cells bsegs m (sh A) k bs RC).
  Qed.
